import { addMonths, format, getDaysInMonth, parseISO, setDate, startOfMonth } from 'date-fns'

/**
 * Money maths for the Finance module — pure, no React, no Dexie, no copy.
 *
 * Everything a couple could argue about is decided here and tested here, so the
 * screens only render numbers they were handed. Per the house rule, this module
 * returns values and keys, never user-facing text.
 *
 * All amounts are whole Rupiah. Rupiah has no practical sub-unit, and a split
 * that does not add back up to the original amount is the fastest way to lose a
 * couple's trust — so every allocation uses largest-remainder and is asserted to
 * sum exactly.
 */

// ---------------------------------------------------------------------------
// Vocabulary
// ---------------------------------------------------------------------------

/** The three spaces: uang saya, uang bersama, uang yang dibagikan. */
export type MoneySpace = 'mine' | 'shared' | 'disclosed'
export const MONEY_SPACES: readonly MoneySpace[] = ['mine', 'shared', 'disclosed']

/** How deep a partner may look into an account. Four steps, not a boolean. */
export type Disclosure = 'privat' | 'ringkasan' | 'kategori' | 'detail'
export const DISCLOSURES: readonly Disclosure[] = ['privat', 'ringkasan', 'kategori', 'detail']

export type ContributionModel =
  | 'sama_rata'
  | 'proporsional'
  | 'sesuai_kebutuhan'
  | 'nominal_tetap'
  | 'per_kategori'
  | 'gantian'
  | 'satu_pihak'
  | 'campuran'
  | 'kesepakatan'

export const CONTRIBUTION_MODELS: readonly ContributionModel[] = [
  'sama_rata',
  'proporsional',
  'sesuai_kebutuhan',
  'nominal_tetap',
  'per_kategori',
  'gantian',
  'satu_pihak',
  'campuran',
  'kesepakatan',
]

/**
 * The eight named presets, in the order the spec lists them. `kesepakatan` is
 * deliberately *not* one of them: it is the escape hatch for a couple whose
 * arrangement is none of the eight, so it has no preset semantics to compare.
 */
export const CONTRIBUTION_PRESETS: readonly ContributionModel[] = [
  'sama_rata',
  'proporsional',
  'sesuai_kebutuhan',
  'satu_pihak',
  'gantian',
  'nominal_tetap',
  'per_kategori',
  'campuran',
]

/** The negotiable half of an agreement. Everything is optional per model. */
export interface RuleTerms {
  model: ContributionModel
  /** proporsional, sesuai_kebutuhan, campuran — monthly income per person. */
  incomes?: Record<string, number>
  /**
   * sesuai_kebutuhan — each person's own monthly essentials (kos, cicilan,
   * kirim ke orang tua). What is left after those is what they can contribute
   * from, so the weights are `income − needs`, not income.
   */
  needs?: Record<string, number>
  /** nominal_tetap, campuran — the fixed rupiah each person puts in first. */
  fixed?: Record<string, number>
  /** per_kategori — category → the person who carries it. */
  byCategory?: Record<string, string>
  /** gantian — the turn order. */
  rotation?: string[]
  /** satu_pihak — the single payer. */
  payerProfileId?: string
  /** kesepakatan — explicit weights, any scale; they are normalised. */
  shares?: Record<string, number>
}

export interface AllocationContext {
  category?: string
  /** Which turn this expense is, for `gantian`. Zero-based. */
  turn?: number
}

// ---------------------------------------------------------------------------
// Allocation
// ---------------------------------------------------------------------------

/**
 * Splits `amount` by `weights` into whole rupiah that sum back to `amount`.
 * Largest-remainder: the pennies go to whoever was rounded down hardest, and
 * ties break on profile id so the same input always gives the same output.
 */
export function distribute(amount: number, weights: Record<string, number>): Record<string, number> {
  const target = Math.round(amount)
  const ids = Object.keys(weights).sort()
  if (ids.length === 0) return {}

  let total = 0
  for (const id of ids) total += Math.max(0, weights[id] ?? 0)
  // A rule with no usable weights (all zero incomes, say) still has to produce
  // an answer — falling back to equal shares beats dividing by zero.
  const effective: Record<string, number> =
    total > 0 ? weights : Object.fromEntries(ids.map((id) => [id, 1]))
  if (total <= 0) total = ids.length

  const out: Record<string, number> = {}
  const remainders: { id: string; frac: number }[] = []
  let assigned = 0
  for (const id of ids) {
    const raw = (target * Math.max(0, effective[id] ?? 0)) / total
    const floor = Math.floor(raw)
    out[id] = floor
    assigned += floor
    remainders.push({ id, frac: raw - floor })
  }

  let left = target - assigned
  remainders.sort((a, b) => b.frac - a.frac || a.id.localeCompare(b.id))
  for (const r of remainders) {
    if (left <= 0) break
    out[r.id] = (out[r.id] ?? 0) + 1
    left--
  }
  return out
}

/** Ratio weights for `proporsional`. Exported because the UI previews them. */
export function incomeWeights(
  participants: string[],
  incomes: Record<string, number> | undefined,
): Record<string, number> {
  return Object.fromEntries(participants.map((p) => [p, Math.max(0, incomes?.[p] ?? 0)]))
}

/**
 * Weights for `sesuai_kebutuhan`: what is left of each income once that person's
 * own declared essentials are paid. Someone whose needs eat their whole income
 * weighs zero — the model's entire point — and if that is true of everyone,
 * `distribute` falls back to equal rather than dividing by nothing.
 */
export function capacityWeights(
  participants: string[],
  incomes: Record<string, number> | undefined,
  needs: Record<string, number> | undefined,
): Record<string, number> {
  return Object.fromEntries(
    participants.map((p) => [
      p,
      Math.max(0, Math.max(0, incomes?.[p] ?? 0) - Math.max(0, needs?.[p] ?? 0)),
    ]),
  )
}

/**
 * Turns one expense into "who owes how much", under the rule that was in force.
 * Unknown/unusable terms degrade to sama rata rather than throwing — a screen
 * mid-setup should still show a plausible preview, never a blank.
 */
export function allocate(
  amount: number,
  participants: string[],
  rule: RuleTerms,
  ctx: AllocationContext = {},
): Record<string, number> {
  const ids = [...new Set(participants)].filter(Boolean)
  if (ids.length === 0) return {}
  const equal = Object.fromEntries(ids.map((p) => [p, 1]))
  // The people who owe nothing still appear with a zero — a share sheet that
  // silently drops a name reads as "we forgot you", which is the wrong feeling.
  const soloIfKnown = (who: string | undefined) =>
    who && ids.includes(who)
      ? distribute(amount, Object.fromEntries(ids.map((p) => [p, p === who ? 1 : 0])))
      : distribute(amount, equal)

  switch (rule.model) {
    case 'proporsional': {
      const w = incomeWeights(ids, rule.incomes)
      return distribute(amount, w)
    }
    case 'sesuai_kebutuhan':
      return distribute(amount, capacityWeights(ids, rule.incomes, rule.needs))
    case 'nominal_tetap':
      return fixedFirst(amount, ids, rule.fixed ?? {})
    case 'campuran':
      // Hybrid: the agreed fixed amounts go in first, and what is still left is
      // shared by income ratio rather than in halves. That is the "sebagian
      // patungan tetap, sisanya ikut penghasilan" arrangement.
      return fixedFirst(amount, ids, rule.fixed ?? {}, incomeWeights(ids, rule.incomes))
    case 'per_kategori':
      return soloIfKnown(ctx.category ? rule.byCategory?.[ctx.category] : undefined)
    case 'gantian': {
      const order = (rule.rotation ?? []).filter((p) => ids.includes(p))
      const ring = order.length > 0 ? order : ids
      const turn = Number.isFinite(ctx.turn) ? Math.max(0, Math.trunc(ctx.turn ?? 0)) : 0
      return soloIfKnown(ring[turn % ring.length])
    }
    case 'satu_pihak':
      return soloIfKnown(rule.payerProfileId)
    case 'kesepakatan':
      return distribute(amount, Object.fromEntries(ids.map((p) => [p, Math.max(0, rule.shares?.[p] ?? 0)])))
    case 'sama_rata':
    default:
      return distribute(amount, equal)
  }
}

/**
 * `nominal_tetap`: each fixed contribution is taken first (capped so the total
 * never exceeds the bill), and whatever is left over is shared equally by the
 * people who had no fixed number — or by everyone, if they all did.
 *
 * `campuran` reuses this with `restWeights` set to the income ratio, so the
 * remainder is shared proportionally instead of equally.
 */
function fixedFirst(
  amount: number,
  ids: string[],
  fixed: Record<string, number>,
  restWeights?: Record<string, number>,
): Record<string, number> {
  const target = Math.round(amount)
  const out: Record<string, number> = Object.fromEntries(ids.map((p) => [p, 0]))
  let left = target
  for (const p of ids) {
    const want = Math.max(0, Math.round(fixed[p] ?? 0))
    const take = Math.min(want, left)
    out[p] = take
    left -= take
  }
  if (left <= 0) return out

  // With explicit remainder weights the leftover is everyone's business (a fixed
  // contribution is a floor, not an exemption); without them the old rule holds
  // and only the people with no fixed number carry the rest.
  const rest = restWeights ? ids : ids.filter((p) => !(fixed[p] ?? 0))
  const spread = distribute(
    left,
    Object.fromEntries((rest.length > 0 ? rest : ids).map((p) => [p, restWeights?.[p] ?? 1])),
  )
  for (const [p, v] of Object.entries(spread)) out[p] = (out[p] ?? 0) + v
  return out
}

// ---------------------------------------------------------------------------
// Settlement
// ---------------------------------------------------------------------------

export interface SplitLike {
  paidByProfileId: string
  amount: number
  /** profileId → rupiah owed. Produced by `allocate` and frozen on the record. */
  shares: Record<string, number>
  settledAt?: string
}

/** Net position per person: positive means they still owe the other side. */
export function balances(splits: SplitLike[]): Record<string, number> {
  const net: Record<string, number> = {}
  const bump = (id: string, by: number) => {
    net[id] = (net[id] ?? 0) + by
  }
  for (const s of splits) {
    if (s.settledAt) continue
    for (const [p, share] of Object.entries(s.shares)) bump(p, Math.round(share))
    bump(s.paidByProfileId, -Math.round(s.amount))
  }
  return net
}

export interface Settlement {
  debtorProfileId: string
  creditorProfileId: string
  amount: number
}

/**
 * One transfer that clears the most of the balance. Deliberately a single
 * neutral line — "siapa perlu menyelesaikan berapa" — and never a running
 * tally of who spends more, which is the same number wearing a judgement.
 */
export function settlement(splits: SplitLike[]): Settlement | null {
  const net = balances(splits)
  let debtor: string | undefined
  let creditor: string | undefined
  for (const id of Object.keys(net).sort()) {
    const v = net[id] ?? 0
    if (debtor === undefined || v > (net[debtor] ?? 0)) debtor = id
    if (creditor === undefined || v < (net[creditor] ?? 0)) creditor = id
  }
  if (!debtor || !creditor || debtor === creditor) return null
  const amount = Math.min(net[debtor] ?? 0, -(net[creditor] ?? 0))
  if (amount < 1) return null
  return { debtorProfileId: debtor, creditorProfileId: creditor, amount }
}

// ---------------------------------------------------------------------------
// Safe to spend
// ---------------------------------------------------------------------------

/** Next occurrence of a day-of-month, strictly after `today`. */
export function nextPayday(today: string, dayOfMonth: number): string {
  const d = parseISO(today)
  const wanted = Math.min(31, Math.max(1, Math.round(dayOfMonth)))
  const on = (base: Date) => setDate(base, Math.min(wanted, getDaysInMonth(base)))
  const thisMonth = on(d)
  // Payday today means the money has already landed; the next one is next month.
  const target = thisMonth > d ? thisMonth : on(addMonths(startOfMonth(d), 1))
  return format(target, 'yyyy-MM-dd')
}

export interface PlannedOutflow {
  amount: number
  /** Undated items are known commitments whose timing is not pinned down. */
  dueDate?: string
}

export interface SafeToSpend {
  /** Conservative figure: assumes every undated commitment lands first. */
  low: number
  /** Optimistic figure: only the dated bills before payday are taken out. */
  high: number
  dated: number
  undated: number
  until: string
}

/**
 * Saldo − tagihan sebelum gajian − komitmen.
 *
 * Two numbers, not one. Bills with a due date before payday are certain;
 * commitments without a date might or might not land first, and pretending to
 * know which would be a forecast this app has no basis for. The range is the
 * honest answer, and the screens always show the caveat next to it.
 */
export function safeToSpend(input: {
  balance: number
  today: string
  paydayDom: number
  planned: PlannedOutflow[]
}): SafeToSpend {
  const until = nextPayday(input.today, input.paydayDom)
  let dated = 0
  let undated = 0
  for (const p of input.planned) {
    const amt = Math.max(0, Math.round(p.amount))
    if (!p.dueDate) undated += amt
    else if (p.dueDate <= until) dated += amt
  }
  const high = Math.round(input.balance) - dated
  return { low: high - undated, high, dated, undated, until }
}

// ---------------------------------------------------------------------------
// Effective-dated agreements
// ---------------------------------------------------------------------------

/**
 * The agreement in force on `date`. A new agreement is a new record, so history
 * is never rewritten: a split from March keeps being explained by the March
 * rule even after the couple changes how they split in July.
 *
 * `rules` is expected in creation order; two rules starting the same day are
 * resolved in favour of the one written later.
 */
export function ruleAt<T extends { effectiveFrom: string }>(rules: T[], date: string): T | undefined {
  let found: T | undefined
  for (const r of rules) {
    if (r.effectiveFrom <= date) {
      if (!found || r.effectiveFrom >= found.effectiveFrom) found = r
    }
  }
  return found
}

// ---------------------------------------------------------------------------
// Purchase proposals
// ---------------------------------------------------------------------------

export type ProposalTier = 'bebas' | 'kasih_tahu' | 'perlu_setuju'

/**
 * Di bawah X bebas · X sampai Y kasih tahu · di atas Y perlu setuju.
 * A reversed pair (Y < X) is treated as Y = X rather than rejected, so a
 * half-filled form still classifies instead of blowing up mid-typing.
 */
export function proposalTier(amount: number, notifyAbove: number, agreeAbove: number): ProposalTier {
  const notify = Math.max(0, notifyAbove)
  const agree = Math.max(notify, agreeAbove)
  const a = Math.max(0, Math.round(amount))
  if (a > agree) return 'perlu_setuju'
  if (a >= notify) return 'kasih_tahu'
  return 'bebas'
}

// ---------------------------------------------------------------------------
// Disclosure
// ---------------------------------------------------------------------------

export interface DisclosedFields {
  /** False means the partner does not even learn the account exists. */
  exists: boolean
  balance: boolean
  categories: boolean
  entries: boolean
}

export function disclosedFields(level: Disclosure): DisclosedFields {
  switch (level) {
    case 'detail':
      return { exists: true, balance: true, categories: true, entries: true }
    case 'kategori':
      return { exists: true, balance: true, categories: true, entries: false }
    case 'ringkasan':
      return { exists: true, balance: true, categories: false, entries: false }
    case 'privat':
    default:
      return { exists: false, balance: false, categories: false, entries: false }
  }
}

export interface EntryLike {
  amount: number
  category: string
}

/** Category totals of the outflows, biggest first. Used by the `kategori` level. */
export function categoryTotals(entries: EntryLike[]): { category: string; amount: number }[] {
  const sums = new Map<string, number>()
  for (const e of entries) {
    if (e.amount >= 0) continue
    sums.set(e.category, (sums.get(e.category) ?? 0) + Math.round(-e.amount))
  }
  return [...sums.entries()]
    .map(([category, amount]) => ({ category, amount }))
    .sort((a, b) => b.amount - a.amount || a.category.localeCompare(b.category))
}
